'use strict';
const D=window.ISKANDER_DATA;
const people=new Map(D.people.map(p=>[p.id,p]));
const works=new Map(D.works.map(w=>[w.id,w]));
const evidence=new Map(D.evidence.map(e=>[e.id,e]));
const semanticRelations=D.relations.filter(r=>r.type!=='co_occurs');
const labels={graph:'Карта связей',people:'Персонажи',works:'Произведения',family:'Семьи',places:'Места'};
const roleNames={main:'Главный герой',secondary:'Второстепенный',episode:'Эпизод',mention:'Упоминание'};
const confidenceNames={explicit:'Прямо в тексте',strongly_implied:'Следует из контекста',inferred:'Интерпретация',uncertain:'Неясно'};
const familyTypes=new Set(['parent','spouse','sibling','grandparent','cousin','avuncular']);
const state={view:'graph',person:'sandro',profile:'overview',graphFilter:'all',graphPage:0,family:'sandro',place:'amra',work:null,workFilter:'pilot',peopleKind:'connected',globalQuery:'',peopleQuery:'',workQuery:''};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const validViews=new Set(Object.keys(labels));
function routeUrl(route={}){const url=new URL(location.href);url.search='';url.hash='';const view=route.view||'graph';url.searchParams.set('view',view);if(route.person)url.searchParams.set('person',route.person);if(route.profile&&route.profile!=='overview')url.searchParams.set('profile',route.profile);if(route.work)url.searchParams.set('work',route.work);if(route.family)url.searchParams.set('family',route.family);if(route.place)url.searchParams.set('place',route.place);if(route.kind)url.searchParams.set('kind',route.kind);if(route.filter)url.searchParams.set('filter',route.filter);if(route.q)url.searchParams.set('q',route.q);if(route.pq)url.searchParams.set('pq',route.pq);if(route.wq)url.searchParams.set('wq',route.wq);return url.pathname+url.search;}
const personUrl=id=>routeUrl({view:'graph',person:id});
const workUrl=id=>routeUrl({view:'works',work:id});
function readRoute(){const q=new URLSearchParams(location.search);const view=q.get('view');state.view=validViews.has(view)?view:'graph';const person=q.get('person');if(person&&people.has(person))state.person=person;state.profile=q.get('profile')==='appearances'?'appearances':'overview';const work=q.get('work');state.work=work&&works.has(work)?work:null;const family=q.get('family');if(family&&typeof families!=='undefined'&&families[family])state.family=family;const place=q.get('place');if(place&&D.places.some(p=>p.id===place))state.place=place;const kind=q.get('kind');state.peopleKind=['connected','all','historical','automatic'].includes(kind)?kind:'connected';const filter=q.get('filter');state.workFilter=['pilot','all','prose','poetry'].includes(filter)?filter:'pilot';state.globalQuery=q.get('q')||'';state.peopleQuery=q.get('pq')||'';state.workQuery=q.get('wq')||'';}
function currentRouteUrl(){const q=state.globalQuery||undefined;if(state.profile==='appearances')return routeUrl({view:'graph',person:state.person,profile:'appearances',q});if(state.view==='graph')return routeUrl({view:'graph',person:state.person,q});if(state.view==='works')return routeUrl({view:'works',work:state.work,filter:state.workFilter,wq:state.workQuery||undefined,q});if(state.view==='family')return routeUrl({view:'family',family:state.family,q});if(state.view==='places')return routeUrl({view:'places',place:state.place,q});if(state.view==='people')return routeUrl({view:'people',kind:state.peopleKind,pq:state.peopleQuery||undefined,q});return routeUrl({view:state.view,q});}
function syncUrl(replace=false){history[replace?'replaceState':'pushState'](null,'',currentRouteUrl());}
const personAnchor=(p,attrs='')=>`<a href="${esc(personUrl(p.id))}" data-person="${esc(p.id)}" data-view="graph" ${attrs}>${esc(p.canonical_name)}</a>`;
const workAnchor=(w,attrs='')=>`<a href="${esc(workUrl(w.id))}" data-work="${esc(w.id)}" ${attrs}>${esc(w.title)}</a>`;
const normalizeName=value=>String(value).trim().toLocaleLowerCase('ru');
const regexEscape=value=>value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const personNames=(()=>{const candidates=[];for(const p of D.people){candidates.push({name:p.canonical_name,id:p.id});for(const a of D.aliases.filter(a=>a.person_id===p.id)){if(/^\p{Lu}/u.test(a.name))candidates.push({name:a.name,id:p.id});}}const owners=new Map;for(const item of candidates){const key=normalizeName(item.name);if(key.length<3)continue;if(!owners.has(key))owners.set(key,new Set);owners.get(key).add(item.id);}return candidates.filter(item=>owners.get(normalizeName(item.name))?.size===1).sort((a,b)=>b.name.length-a.name.length);})();
const personNamePattern=personNames.length?new RegExp(`(?<![\\p{L}\\p{N}_])(?:${[...new Set(personNames.map(item=>regexEscape(item.name)))].join('|')})(?![\\p{L}\\p{N}_])`,'giu'):null;
const personByName=new Map(personNames.map(item=>[normalizeName(item.name),item.id]));
function linkPeople(value,exclude=[]){const text=String(value??'');if(!personNamePattern)return esc(text);const excluded=new Set(Array.isArray(exclude)?exclude:[exclude]);let html='',last=0;personNamePattern.lastIndex=0;for(const match of text.matchAll(personNamePattern)){const id=personByName.get(normalizeName(match[0]));if(!id||excluded.has(id))continue;html+=esc(text.slice(last,match.index))+`<a class="person-link" href="${esc(personUrl(id))}" data-person="${esc(id)}" data-view="graph">${esc(match[0])}</a>`;last=match.index+match[0].length;}return html+esc(text.slice(last));}
const textWord=n=>n%10===1&&n%100!==11?'текст':n%10>=2&&n%10<=4&&!(n%100>=12&&n%100<=14)?'текста':'текстов';
const initials=name=>name.replace(/[«»()]/g,'').split(/[\s-]+/).filter(Boolean).slice(0,2).map(n=>n[0]).join('');
const quoteButton=(ids,label='Открыть цитату')=>`<button class="text-button" data-evidence="${esc(ids.join(','))}">${esc(label)}</button>`;
const getRelations=id=>semanticRelations.filter(r=>r.from_person===id||r.to_person===id);
const visibleByRule=p=>getRelations(p.id).some(r=>other(r,p.id)?.id!=='narrator');
const other=(r,id)=>people.get(r.from_person===id?r.to_person:r.from_person);
function title(heading,description,eyebrow='ЛЮДИ И ИСТОРИИ'){return `<div class="title-row"><div><span class="eyebrow">${eyebrow}</span><h1>${heading}</h1><p class="subtitle">${description}</p></div><div class="stats"><div class="stat"><b>${D.people.length}</b><span>персонажей в базе</span></div><div class="stat"><b>${semanticRelations.length}</b><span>смысловых связей</span></div><div class="stat"><b>${D.meta.automatic_work_count||D.meta.pilot_count}</b><span>${textWord(D.meta.automatic_work_count||D.meta.pilot_count)} просмотрено</span></div></div></div>`;}
function profile(id){const p=people.get(id);const appearances=D.appearances.filter(a=>a.person_id===id);const aliases=[...new Set(D.aliases.filter(a=>a.person_id===id).map(a=>a.name))].filter(n=>n!==p.canonical_name);const automatic=p.id.startsWith('bulk_');return `<aside class="panel person-card"><div class="portrait">${esc(initials(p.canonical_name))}</div><span class="eyebrow">${automatic?'АВТОМАТИЧЕСКИЙ КАНДИДАТ':p.kind==='historical'?'ИСТОРИЧЕСКОЕ ЛИЦО В ТЕКСТЕ':p.kind==='narrator'?'ГОЛОС РАССКАЗА':p.kind==='animal'?'ЖИВОТНОЕ В РАССКАЗЕ':'ПЕРСОНАЖ'}</span><h2>${esc(p.canonical_name)}</h2><span class="tag ${automatic?'amber':'green'}">${appearances.length} ${textWord(appearances.length)}${automatic?' · проверить':' в пилоте'}</span><p class="description">${linkPeople(p.description,id)}</p>${quoteButton(p.evidence,'На чём основано описание ↗')}${aliases.length?`<div class="profile-sep"></div><p class="mini-heading">В тексте также</p><p class="subtitle">${aliases.map(esc).join(' · ')}</p>`:''}<div class="profile-sep"></div><p class="mini-heading">Появляется в произведениях</p>${appearances.map(a=>`<div class="work-item">${workAnchor(works.get(a.work_id))}<div class="work-meta">${automatic?'автоматическое совпадение имени':roleNames[a.role]} · том ${works.get(a.work_id).volume}</div></div>`).join('')}<div class="profile-actions"><a class="button primary" href="${esc(routeUrl({view:'graph',person:id,profile:'appearances'}))}" data-profile="appearances" data-person="${id}">Где ещё появляется ↗</a><a class="button" href="${esc(personUrl(id))}" data-person="${id}" data-view="graph">Связи</a></div>${p.notes?`<div class="data-scope">${linkPeople(p.notes,id)}</div>`:''}</aside>`;}
function graph(id){let relations=getRelations(id).filter(r=>r.status!=='rejected');if(state.graphFilter==='family')relations=relations.filter(r=>familyTypes.has(r.type));if(state.graphFilter==='direct')relations=relations.filter(r=>r.status==='accepted'&&r.confidence==='explicit');const allNeighbors=[...new Set(relations.map(r=>other(r,id).id))];const pageSize=window.innerWidth<1000?8:12;const pages=Math.max(1,Math.ceil(allNeighbors.length/pageSize));state.graphPage%=pages;let neighbors=allNeighbors.slice(state.graphPage*pageSize,(state.graphPage+1)*pageSize);const width=820,height=650,cx=410,cy=302;const p=people.get(id);const positions=new Map([[id,{x:cx,y:cy}]]);neighbors.forEach((n,i)=>{const angle=-Math.PI/2+i*Math.PI*2/neighbors.length;positions.set(n,{x:cx+270*Math.cos(angle),y:cy+235*Math.sin(angle)});});let edges='';for(const n of neighbors){const r=relations.find(r=>other(r,id).id===n);const pt=positions.get(n);edges+=`<g class="graph-edge"><line x1="${cx}" y1="${cy}" x2="${pt.x}" y2="${pt.y}" class="graph-line ${familyTypes.has(r.type)?'family':''} ${r.status==='reported'?'reported':''}"/><title>${esc(r.label)}</title></g>`;}
let nodes=[id,...neighbors].map(n=>{const pt=positions.get(n),person=people.get(n),center=n===id;const words=person.canonical_name.split(' ');let lines=words.length>2?[words.slice(0,2).join(' '),words.slice(2).join(' ')]:[person.canonical_name];return `<g class="graph-node ${center?'center':''}" tabindex="0" role="button" aria-label="Открыть ${esc(person.canonical_name)}" data-person="${n}" transform="translate(${pt.x},${pt.y})"><title>${esc(person.canonical_name)}</title><circle r="${center?48:27}"/><text class="graph-initial" text-anchor="middle" dominant-baseline="central">${esc(initials(person.canonical_name))}</text>${lines.map((line,i)=>`<text class="graph-name" text-anchor="middle" y="${(center?73:48)+i*19}">${esc(line)}</text>`).join('')}</g>`;}).join('');return `<div class="panel"><div class="graph-head"><span class="panel-label">Окружение · ${esc(p.canonical_name)}</span><div class="graph-controls"><select id="graph-filter" aria-label="Тип связей"><option value="all" ${state.graphFilter==='all'?'selected':''}>Все связи</option><option value="family" ${state.graphFilter==='family'?'selected':''}>Только родство</option><option value="direct" ${state.graphFilter==='direct'?'selected':''}>Прямо в тексте</option></select><button class="button" data-person="sandro" title="Вернуться к Сандро">В центр</button></div></div><div class="graph-stage"><svg viewBox="0 0 ${width} ${height}" role="group" aria-label="Граф связей ${esc(p.canonical_name)}">${edges}${nodes}</svg>${!neighbors.length?'<p class="empty">Связей с этим фильтром пока нет.</p>':''}<span class="graph-note">${neighbors.length} из ${allNeighbors.length} связей · выберите героя</span></div><div class="legend">${pages>1?`<button class="text-button" data-graph-next>Ещё связи · ${state.graphPage+1}/${pages} →</button>`:''}<span><i></i>Социальная связь</span><span><i class="family"></i>Родство</span><span><i class="reported"></i>По словам героя</span></div></div>`;}
function relationRows(relations,id=null){return `<div class="rel-list">${relations.map(r=>{const a=people.get(r.from_person),b=people.get(r.to_person);const target=id?other(r,id):b;return `<article class="rel-row"><span class="tiny-portrait">${esc(initials(target.canonical_name))}</span><div>${id?personAnchor(target):personAnchor(a)+' → '+personAnchor(b)}<small>${linkPeople(r.label)} · <span class="confidence">${confidenceNames[r.confidence]}</span>${r.status==='reported'?' · по словам героя':''}</small>${r.status==='rejected'?'<span class="tag red">Опровергнуто рассказчиком</span>':''}${r.note?`<small>${linkPeople(r.note)}</small>`:''}</div>${quoteButton(r.evidence,'Цитата ↗')}</article>`;}).join('')||'<p class="empty">В пилоте для этого персонажа ещё нет связей.</p>'}</div>`;}
function graphPage(){const rels=getRelations(state.person);return title('Карта связей','Выберите героя — и пройдите по его семье, знакомым и книгам.')+`<div class="workspace">${graph(state.person)}${profile(state.person)}</div><h2 class="section-title">Что их связывает <span class="small-count">${rels.length}</span></h2><div class="relation-columns">${relationRows(rels,state.person)}</div>`;}
function personTiles(list){return list.map(p=>`<article class="entity-tile"><span class="tiny-portrait" style="margin-bottom:16px">${esc(initials(p.canonical_name))}</span><h3>${personAnchor(p)}</h3><p>${linkPeople(p.description,p.id)}</p><span class="source-count">${D.appearances.filter(a=>a.person_id===p.id).length} ${D.appearances.filter(a=>a.person_id===p.id).length===1?'текст':'текста'} · ${getRelations(p.id).length} связей</span></article>`).join('');}
function peopleList(){const query=normalizeName(state.peopleQuery);return D.people.filter(p=>state.peopleKind==='all'||state.peopleKind==='historical'&&p.kind==='historical'||state.peopleKind==='automatic'&&p.id.startsWith('bulk_')||state.peopleKind==='connected'&&visibleByRule(p)).filter(p=>!query||normalizeName([p.canonical_name,p.description,...D.aliases.filter(a=>a.person_id===p.id).map(a=>a.name)].join(' ')).includes(query));}
function peopleResults(){const list=peopleList();return `<p class="small-count people-count">Найдено ${list.length} из ${D.people.length}</p><div class="collection-grid">${personTiles(list)}</div>${list.length?'':'<div class="panel empty">Персонажи не найдены. Попробуйте имя, прозвище или слово из описания.</div>'}`;}
function peoplePage(){const connected=D.people.filter(visibleByRule);return title('Люди литературного мира','По умолчанию показаны герои хотя бы с одной смысловой связью не только с рассказчиком.')+`<div class="section-tools"><div class="section-search"><label for="people-search">Поиск в персонажах</label><input id="people-search" type="search" value="${esc(state.peopleQuery)}" placeholder="Имя, прозвище или описание…" autocomplete="off"></div><div class="filters"><button class="button ${state.peopleKind==='connected'?'active':''}" data-people-kind="connected">Связанные · ${connected.length}</button><button class="button ${state.peopleKind==='all'?'active':''}" data-people-kind="all">Все · ${D.people.length}</button><button class="button ${state.peopleKind==='historical'?'active':''}" data-people-kind="historical">Исторические</button><button class="button ${state.peopleKind==='automatic'?'active':''}" data-people-kind="automatic">Автоматические</button></div></div><div id="people-results">${peopleResults()}</div>`;}
function appearancesPage(){const p=people.get(state.person),confirmed=D.appearances.filter(a=>a.person_id===p.id);const hits=D.corpusHits.filter(h=>h.person_id===p.id).sort((a,b)=>b.count-a.count);return title(`Где ещё появляется ${esc(p.canonical_name)}`,'Подтверждённые появления отдельно от совпадений имени.','ПУТЬ ГЕРОЯ ПО КНИГАМ')+`<div class="reading-layout"><div><h2 class="section-title" style="margin-top:0">Прочитано в пилоте · ${confirmed.length}</h2><div class="panel content-pad">${confirmed.map(a=>{const w=works.get(a.work_id);return `<article class="hit-row"><span class="tag green">${roleNames[a.role]}</span><h3 style="margin-top:12px"><button data-work="${w.id}">${esc(w.title)}</button></h3><p>Том ${w.volume} · ${w.kind==='novel_chapter'?'Глава романа':'Текст канонического собрания'}</p>${quoteButton(a.evidence,'Посмотреть появление ↗')}</article>`;}).join('')}</div><h2 class="section-title">Есть совпадения имени · ${hits.length}</h2><p class="subtitle" style="margin-bottom:18px">Здесь ещё нужно проверить, тот ли это герой. Число означает найденные формы имени, а не количество сцен.</p><div class="panel content-pad">${hits.map(h=>{const w=works.get(h.work_id);return `<article class="hit-row"><h3><button data-work="${w.id}">${esc(w.title)}</button></h3><span class="tag amber">Не проверено</span> <span class="small-count">Том ${w.volume} · ${h.count} совпадений</span><p>${esc(evidence.get(h.evidence_id).quote)}</p>${quoteButton([h.evidence_id],'Открыть источник ↗')}</article>`;}).join('')||'<p class="subtitle">Автоматический поиск не дал совпадений. Это не доказывает, что герой больше нигде не появляется: поиск пока не распознаёт все описания и местоимения.</p>'}</div></div>${profile(p.id)}</div>`;}
const kindNames={novel:'Роман',cycle:'Цикл',work:'Произведение',cycle_story:'Рассказ цикла',novel_chapter:'Глава романа',work_part:'Часть произведения',poem:'Стихотворение / баллада',long_poem:'Поэма',epigram:'Эпиграмма / шутка',translation:'Перевод',essay:'Эссе',notes:'Записки'};
function workTable(query=''){const q=query.toLocaleLowerCase('ru');const rows=D.works.filter(w=>(state.workFilter==='all'||state.workFilter==='pilot'&&(w.pilot||w.automatic)||state.workFilter==='prose'&&['novel','cycle','work','cycle_story','novel_chapter','work_part'].includes(w.kind)||state.workFilter==='poetry'&&['poem','long_poem','epigram','translation'].includes(w.kind))&&w.title.toLocaleLowerCase('ru').includes(q)).sort((a,b)=>(a.volume??0)-(b.volume??0)||a.title.localeCompare(b.title,'ru'));return `<p class="small-count">Показано ${rows.length} из ${D.works.length} записей. Включены целые произведения и их части.</p><div class="panel"><table class="work-table"><thead><tr><th class="number">Том</th><th>Название</th><th>Разбор</th></tr></thead><tbody>${rows.map(w=>`<tr><td class="number">${w.volume??'—'}</td><td>${workAnchor(w)}<div class="work-meta">${kindNames[w.kind]||w.kind}${w.parent_id?' · '+esc(works.get(w.parent_id)?.title):''}</div></td><td>${w.pilot?'<span class="tag green">Пилот</span>':w.automatic?'<span class="tag amber">Авто · проверить</span>':'<span class="small-count">В реестре</span>'}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">По этому запросу ничего не найдено.</div>'}</div>`;}
function worksPage(){if(state.work)return workPage(state.work);return title('Произведения','Десять томов, отдельные тексты и части больших историй.','КАНОНИЧЕСКОЕ СОБРАНИЕ')+`<div class="section-tools"><div class="section-search"><label for="work-search">Поиск в произведениях</label><input id="work-search" type="search" value="${esc(state.workQuery)}" placeholder="Название произведения…" autocomplete="off"></div><div class="filters">${[['pilot','Разобраны'],['all','Весь реестр · '+D.works.length],['prose','Проза'],['poetry','Поэзия и переводы']].map(([id,name])=>`<button class="button ${state.workFilter===id?'active':''}" data-work-filter="${id}">${name}</button>`).join('')}</div></div><div id="work-results">${workTable(state.workQuery)}</div>`;}
function workPage(id){const w=works.get(id);const appearances=D.appearances.filter(a=>a.work_id===id);const children=D.works.filter(c=>c.parent_id===id);const hits=D.corpusHits.filter(h=>h.work_id===id);return `<button class="text-button" data-work-back style="margin-bottom:22px">← Все произведения</button>`+title(esc(w.title),`${w.volume?'Том '+w.volume+' · ':''}${kindNames[w.kind]||w.kind}`,'ПРОИЗВЕДЕНИЕ')+`<div class="panel content-pad">${w.pilot?`<span class="tag green">Разобрано в пилоте</span><h2 class="section-title">Персонажи · ${appearances.length}</h2><div class="rel-list">${appearances.sort((a,b)=>Object.keys(roleNames).indexOf(a.role)-Object.keys(roleNames).indexOf(b.role)).map(a=>{const p=people.get(a.person_id);return `<article class="rel-row"><span class="tiny-portrait">${esc(initials(p.canonical_name))}</span><div><button data-person="${p.id}" data-view="graph">${esc(p.canonical_name)}</button><small>${roleNames[a.role]} · роль оценена при чтении</small></div>${quoteButton(a.evidence,'Фрагмент ↗')}</article>`;}).join('')}</div>`:`<p class="subtitle">${children.length?'Это объединяющая запись. Откройте одну из частей ниже.':'Текст есть в корпусе, но полный разбор персонажей ещё не выполнен.'}</p>`}${children.length?`<h2 class="section-title">Части · ${children.length}</h2><div class="rel-list">${children.map(c=>`<div class="rel-row"><div><button data-work="${c.id}">${esc(c.title)}</button><small>${c.pilot?'Разобрано в пилоте':'В реестре'}</small></div></div>`).join('')}</div>`:''}${hits.length?`<h2 class="section-title">Совпадения имён</h2><p class="subtitle" style="margin-bottom:15px">Возможные появления известных героев; идентичность ещё не проверена.</p><div class="rel-list">${hits.map(h=>`<div class="rel-row"><div><button data-person="${h.person_id}" data-view="graph">${esc(people.get(h.person_id).canonical_name)}</button><small>${h.count} совпадений · не проверено</small></div>${quoteButton([h.evidence_id],'Фрагмент ↗')}</div>`).join('')}</div>`:''}</div>`;}
const families={chik:{name:'Семья Чика',nodes:{chik_grandmother:[100,65],chik_aunt:[300,65],chik_uncle_riza:[520,65],chik_uncle_kolya:[700,65],chik_mother:[180,250],chik_father:[400,250],chik_older_brother:[90,420],chik:[310,420],chik_sister:[570,420]}},sandro:{name:'Семья Сандро',nodes:{father_sandro:[300,55],wife_habug:[520,55],brother_sandro:[100,225],isa:[300,225],sandro:[520,225],katya:[700,225],granddaughter:[100,410],tali:[610,410]}},katya_family:{name:'Семья тёти Кати',nodes:{katya_grandmother:[180,80],katya:[390,300],sandro:[650,300]}},kyzym:{name:'Семья Кязыма',nodes:{father_sandro:[170,65],wife_habug:[390,65],kyzym:[280,230],nutsa:[540,230],kyzym_son:[280,410],kyzym_daughter:[570,410]}},mahaz:{name:'Семья Махаза',nodes:{brother_sandro:[280,90],masha:[520,90],firuza:[220,330],lena_masha:[580,330]}},isa:{name:'Семья Исы',nodes:{isa:[280,90],isa_wife:[520,90],adgur:[180,330],zarifa:[400,330],katusha:[620,330]}},tali:{name:'Семья Тали',nodes:{sandro:[230,80],katya:[470,80],tali:[350,270],bagrat:[610,270]}},shashiko:{name:'Семья Щащико',nodes:{shashiko_mother:[220,70],shashiko_brother:[220,250],shashiko:[450,250],shashiko_wife:[650,250],shashiko_son:[550,420]}},narrator:{name:'Семья рассказчика',nodes:{narrator_mother:[270,100],narrator_father:[530,100],narrator:[400,340]}},lakoba:{name:'Семья Лакобы',nodes:{lakoba:[400,90],sarya_lakoba:[620,90],rauf_lakoba:[400,330]}},tobacconist:{name:'Семья табачника',nodes:{tab_mother:[500,60],tobacconist:[270,225],tab_wife:[500,225],tab_son:[260,410],tab_daughter:[520,410]}},lamba:{name:'Братья Ламба',nodes:{lamba_father:[400,80],lamba_elder:[220,300],lamba_younger:[580,300]}},shop:{name:'Семья лавочника',nodes:{shopkeeper:[270,100],shop_wife:[530,100],shop_son:[400,330]}},girl:{name:'Семья девочки',nodes:{girl_father:[260,100],girl_mother:[540,100],girl_amra:[400,330]}},german_sisters:{name:'Сёстры из Восточной Пруссии',nodes:{german_uncle:[400,70],german_katrin:[250,300],greta:[550,300]}},vakhtang_family:{name:'Семья Вахтанга',nodes:{vakhtang_father:[270,100],vakhtang_mother:[530,100],vakhtang:[400,340]}},adamyr_family:{name:'Семья Адамыра',nodes:{adamyr_mother:[400,90],adamyr:[400,330]}}};
function familyPage(){const f=families[state.family];const ids=Object.keys(f.nodes);const rels=D.relations.filter(r=>familyTypes.has(r.type)&&r.status!=='rejected'&&r.confidence!=='uncertain'&&ids.includes(r.from_person)&&ids.includes(r.to_person));let svg=rels.map(r=>{const a=f.nodes[r.from_person],b=f.nodes[r.to_person];return `<g><line class="family-line" x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}"/><text class="graph-edge-label" text-anchor="middle" x="${(a[0]+b[0])/2}" y="${(a[1]+b[1])/2-9}">${esc(r.label.toLocaleLowerCase('ru'))}</text></g>`;}).join('');svg+=ids.map(id=>{const [x,y]=f.nodes[id];const p=people.get(id);const words=p.canonical_name.split(' '),lines=words.length>2?[words.slice(0,2).join(' '),words.slice(2).join(' ')]:[p.canonical_name];return `<g class="graph-node" role="button" tabindex="0" data-person="${id}" data-view="graph" aria-label="Открыть ${esc(p.canonical_name)}" transform="translate(${x},${y})"><rect class="family-box" x="-105" y="-35" rx="7" width="210" height="70"/>${lines.map((line,i)=>`<text class="family-name" text-anchor="middle" y="${lines.length===1?5:-3+i*21}">${esc(line)}</text>`).join('')}</g>`;}).join('');return title('Семьи и родство','Только связи, для которых есть основание в прочитанном тексте.','ПОКОЛЕНИЯ')+`<div class="family-selector">${Object.entries(families).map(([id,f])=>`<button class="button ${state.family===id?'active':''}" data-family="${id}">${f.name}</button>`).join('')}</div><div class="panel"><div class="graph-head"><span class="panel-label">${f.name}</span><span class="tag">Пропуски оставлены открытыми</span></div><div class="family-scroll"><svg class="family-svg" viewBox="0 0 800 490" role="group" aria-label="${f.name}">${svg}</svg></div></div>${state.family==='chik'?'<div class="notice">Имена родителей, бабушки, старшего брата, сестры и тётушки Чика в прочитанных рассказах не названы. Они сохранены как отдельные семейные роли, без выдуманных имён.</div>':''}${state.family==='sandro'?'<div class="notice">Хабуг прямо назван отцом Сандро. Щащико не показан в дереве: текст говорит о дальнем родстве, но не задаёт его точную линию; двоюродное родство отдельно опровергнуто.</div>':''}${state.family==='katya_family'?'<div class="notice">Происхождение бабушки Кати передано со слов Аслана; в данных связь имеет статус reported.</div>':''}${state.family==='girl'?'<div class="notice">Обращение «Дедушка Ленин» не устанавливает родство девочки со Степаном Тимофеевичем.</div>':''}<h2 class="section-title">Основания связей</h2>${relationRows(rels)}`;}
function placesPage(){const p=D.places.find(p=>p.id===state.place);const links=D.personPlaces.filter(l=>l.place_id===p.id);return title('Места, к которым ведут истории','Схема литературных мест. Расстояния и расположение условны.','ГЕОГРАФИЯ ПОВЕСТВОВАНИЯ')+`<div class="workspace"><div class="panel map-panel"><div class="map-stage" aria-label="Условная схема мест">${D.places.map(place=>`<button class="place-pin ${place.id===p.id?'active':''}" style="left:${place.x}%;top:${place.y}%" data-place="${place.id}">${esc(place.name)}<span>${esc(place.kind)}</span></button>`).join('')}</div><p class="map-caption">Не географическая карта · координаты не приписаны вымышленным и неназванным местам</p></div><aside class="panel person-card"><span class="eyebrow">${esc(p.kind.toUpperCase())}</span><h2>${esc(p.name)}</h2><p class="description">${linkPeople(p.description)}</p>${quoteButton(p.evidence,'Место в тексте ↗')}<div class="profile-sep"></div><p class="mini-heading">Кто здесь появляется</p>${links.map(l=>`<div class="work-item"><button data-person="${l.person_id}" data-view="graph">${esc(people.get(l.person_id).canonical_name)}</button><div class="work-meta">${linkPeople(l.label)} · ${quoteButton([l.evidence_id],'цитата')}</div></div>`).join('')}</aside></div>`;}
function currentLabel(){if(state.profile==='appearances')return `Появления · ${people.get(state.person).canonical_name}`;if(state.view==='graph')return `Карта · ${people.get(state.person).canonical_name}`;if(state.view==='works'&&state.work)return `Произведение · ${works.get(state.work).title}`;if(state.view==='family')return families[state.family].name;if(state.view==='places')return `Место · ${D.places.find(p=>p.id===state.place).name}`;return labels[state.view]||'Персонаж';}
function render(){const label=currentLabel();document.getElementById('current-view').textContent=label;document.querySelectorAll('[data-view].nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false');});const renderers={graph:graphPage,people:peoplePage,works:worksPage,family:familyPage,places:placesPage};document.getElementById('content').innerHTML=state.profile==='appearances'?appearancesPage():renderers[state.view]();document.getElementById('search').value=state.globalQuery;document.title=label+' — Мир Искандера';}
function showEvidence(ids,heading='Основание в тексте'){document.getElementById('evidence-title').textContent=heading;document.getElementById('evidence-content').innerHTML=[...new Set(ids)].map(id=>{const e=evidence.get(id);if(!e)return '';const w=works.get(e.work_id);return `<article class="quote-card"><span class="eyebrow">ТОМ ${w?.volume??'—'} · ${e.paragraph_key?'АБЗАЦ '+Number(e.paragraph_key.slice(3)):'ФРАГМЕНТ'}</span><h3>${esc(w?.title)}</h3><blockquote>${linkPeople(e.quote)}</blockquote><div class="quote-location">${esc(e.location)}<br>Символы ${e.start_char}–${e.end_char} · канонический источник</div></article>`;}).join('');const dialog=document.getElementById('evidence-dialog');if(!dialog.open)dialog.showModal();}
document.addEventListener('click',event=>{const button=event.target.closest('[data-person],[data-evidence],[data-close],[data-view],[data-work],[data-profile],[data-family],[data-place],[data-work-filter],[data-work-back],[data-people-kind],[data-graph-next],[data-history-back],[data-history-forward]');if(!button)return;if(button.matches('a')&&(event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey))return;if(button.matches('a'))event.preventDefault();if(button.hasAttribute('data-history-back'))return history.back();if(button.hasAttribute('data-history-forward'))return history.forward();if(button.hasAttribute('data-close'))return document.getElementById('evidence-dialog').close();if(button.dataset.evidence)return showEvidence(button.dataset.evidence.split(','));const primaryNavigation=button.classList.contains('nav-item')||button.hasAttribute('data-nav-root');const fromGlobalSearch=Boolean(button.closest('#search-results'));if(primaryNavigation){state.globalQuery='';state.peopleQuery='';state.workQuery='';}else if(fromGlobalSearch){state.globalQuery='';}state.profile='overview';if(button.dataset.person){state.person=button.dataset.person;state.graphPage=0;const dialog=document.getElementById('evidence-dialog');if(dialog.open)dialog.close();}if(button.dataset.view){state.view=button.dataset.view;state.work=null;}if(button.dataset.profile)state.profile=button.dataset.profile;if(button.dataset.work){state.work=button.dataset.work;state.view='works';}if(button.hasAttribute('data-work-back')){state.work=null;state.view='works';}if(button.dataset.workFilter)state.workFilter=button.dataset.workFilter;if(button.dataset.family)state.family=button.dataset.family;if(button.dataset.place)state.place=button.dataset.place;if(button.dataset.peopleKind)state.peopleKind=button.dataset.peopleKind;if(button.hasAttribute('data-graph-next'))state.graphPage++;document.getElementById('search-results').hidden=true;if(!button.hasAttribute('data-graph-next'))syncUrl();render();document.getElementById('main').scrollIntoView({block:'start',behavior:'instant'});});
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('.graph-node')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',event=>{if(event.target.id==='graph-filter'){state.graphFilter=event.target.value;state.graphPage=0;render();}});
document.getElementById('search').addEventListener('input',event=>{state.globalQuery=event.target.value.trim();const q=state.globalQuery.toLocaleLowerCase('ru'),container=document.getElementById('search-results');syncUrl(true);container.hidden=!q;if(!q)return;const foundPeople=D.people.filter(p=>(p.canonical_name+' '+p.description+' '+D.aliases.filter(a=>a.person_id===p.id).map(a=>a.name).join(' ')).toLocaleLowerCase('ru').includes(q)).slice(0,12);const foundWorks=D.works.filter(w=>w.title.toLocaleLowerCase('ru').includes(q)).slice(0,8);container.innerHTML=(foundPeople.length?`<p class="search-heading">Персонажи</p>${foundPeople.map(p=>personAnchor(p)).join('')}`:'')+(foundWorks.length?`<p class="search-heading">Произведения</p>${foundWorks.map(w=>workAnchor(w)).join('')}`:'')||'<p>Ничего не найдено.</p>';});
document.addEventListener('input',event=>{if(event.target.id==='people-search'){state.peopleQuery=event.target.value;document.getElementById('people-results').innerHTML=peopleResults();syncUrl(true);}if(event.target.id==='work-search'){state.workQuery=event.target.value;document.getElementById('work-results').innerHTML=workTable(state.workQuery);syncUrl(true);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.getElementById('search-results').hidden=true;});
document.getElementById('evidence-dialog').addEventListener('click',event=>{if(event.target===event.currentTarget&&event.offsetX<0)event.currentTarget.close();});
document.getElementById('about').addEventListener('click',()=>{document.getElementById('evidence-title').textContent='Личный литературный атлас';document.getElementById('evidence-content').innerHTML=`<p>В основе — десять томов издательства «Время». Для начала разобраны три связанных текста: две первые главы «Сандро из Чегема» и «Ленин и дядя Сандро».</p><p>${D.people.length} персонажей и ${D.relations.length} связей снабжены фрагментами из книг. Роль героя — редакционная оценка. Пунктир на графе означает, что о встрече или связи рассказывает сам персонаж.</p><p>Поиск по остальному собранию находит совпадения имён. Они не считаются подтверждёнными повторными появлениями.</p><p>Режим без спойлеров пока не реализован: цитаты и описания могут раскрывать сюжет.</p>`;document.getElementById('evidence-dialog').showModal();});
window.addEventListener('popstate',()=>{readRoute();render();document.getElementById('main').scrollIntoView({block:'start',behavior:'instant'});});
families.chik={name:'Семья Чика',nodes:{father_sandro:[90,45],wife_habug:[300,45],persian_consul:[690,45],sandro:[70,180],kyzym:[260,180],chik_mother:[450,180],chik_aunt_husband:[670,180],chik_father:[450,310],chik_aunt:[680,310],chik_older_brother:[240,445],chik:[450,445],chik_sister:[670,445]}};
readRoute();syncUrl(true);render();
